from urllib.parse import urlencode

IGNORED_VALUES = {None, "", "all", "全部"}
VALID_ORDERS = {"updatedAt", "createdAt", "hits", "score"}


def clean(value):
    if value in IGNORED_VALUES:
        return ""
    value = str(value).strip()
    if value in IGNORED_VALUES:
        return ""
    return value


def int_or_default(value, default):
    try:
        num = int(value)
        return num if num > 0 else default
    except (TypeError, ValueError):
        return default


def execute(node_id, node_data, context):
    params = {}
    page_num = int_or_default(context.get("page_num"), 1)
    if page_num > 1:
        params["page"] = page_num

    tag = clean(context.get("tag"))
    year = clean(context.get("year"))
    area = clean(context.get("area"))
    order = clean(context.get("order")) or "updatedAt"
    keyword = clean(context.get("keyword"))

    if tag:
        params["tag"] = tag
    if year:
        params["year"] = year
    if area:
        params["area"] = area
    if order in VALID_ORDERS:
        params["order"] = order
    if keyword:
        params["q"] = keyword

    query = urlencode(params)
    context["list_path"] = "/videos" + (("?" + query) if query else "")

