    marker = '"' + key + '"'
    while True:
        idx = text.find(marker, pos)
        if idx < 0:
            return -1
        cur = idx + len(marker)
        while cur < len(text) and text[cur].isspace():
            cur += 1
        if cur < len(text) and text[cur] == ':':
            cur += 1
            while cur < len(text) and text[cur].isspace():
                cur += 1
            if expected is None or (cur < len(text) and text[cur] == expected):
                return cur
        pos = idx + len(marker)


def extract_json_range(text, start):
    if start < 0 or start >= len(text):
        return None, start
    pairs = {"{": "}", "[": "]"}
    open_ch = text[start]
    close_ch = pairs.get(open_ch)
    if not close_ch:
        return None, start
    depth = 0
    in_string = False
    escaped = False
    for idx in range(start, len(text)):
        ch = text[idx]
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
        else:
            if ch == '"':
                in_string = True
            elif ch == open_ch:
                depth += 1
            elif ch == close_ch:
                depth -= 1
                if depth == 0:
                    return text[start:idx + 1], idx + 1
    return None, start


