            "title": title,
            "cover": video.get("pic") or video.get("picThumb") or "",
            "rating": normalize_score(video.get("score")),
            "misc": misc,
            "category": category,
            "uploader": video.get("sourceName") or video.get("studio") or "TvTFun",
            "uploaded_at": short_date(video.get("updatedAt") or video.get("publishedAt") or video.get("createdAt")),
            "media_type": "video",
        })

    total = extract_scalar(data, "total", videos_end)
    page = extract_scalar(data, "page", videos_end) or 1
    page_size = extract_scalar(data, "pageSize", videos_end) or 24
    try:
        total_pages = (int(total) + int(page_size) - 1) // int(page_size) if total is not None else None
    except Exception:
        total_pages = None

    context["available_tags"] = tags if isinstance(tags, list) else []
    context["available_years"] = years if isinstance(years, list) else []
    context["available_areas"] = areas if isinstance(areas, list) else []
    context["search_result"] = {
        "total": total,
        "totalPages": total_pages,
        "page": page,
        "items": items,
    }

