import json
import re
from urllib.parse import quote, urljoin


def normalize_video_type(value, url):
    value = str(value or "").lower()
    url = str(url or "").lower().split("?", 1)[0]
    if value in {"hls", "m3u8"} or url.endswith(".m3u8"):
        return "hls"
    if value in {"dash", "mpd"} or url.endswith(".mpd"):
        return "dash"
    if value == "flv" or url.endswith(".flv"):
        return "flv"
    return "mp4"


def normalize_color(value):
    if value is None or value == "":
        return "#ffffff"
    if isinstance(value, int):
        return "#%06x" % (value & 0xFFFFFF)
    text = str(value).strip()
    if text.startswith("#"):
        return text
    try:
        return "#%06x" % (int(text) & 0xFFFFFF)
    except ValueError:
        return text or "#ffffff"


def normalize_mode(value):
    if isinstance(value, str):
        value = value.lower().strip()
        if value in {"scroll", "top", "bottom"}:
            return value
        try:
            value = int(value)
        except ValueError:
            return "scroll"
    if value in {4, "4"}:
        return "bottom"
    if value in {5, "5"}:
        return "top"
    return "scroll"


def normalize_start(value):
    try:
        return max(0, int(float(value) * 1000))
    except (TypeError, ValueError):
        return 0


def extract_share_media_url(share_url, share_html):
    if not share_html:
        return ""
    match = re.search(r'(?:const|let|var)\s+url\s*=\s*"([^"]+)"', share_html, re.S)
    if not match:
        match = re.search(r"(?:const|let|var)\s+url\s*=\s*'([^']+)'", share_html, re.S)
    if not match:
        return ""
    value = match.group(1).replace("\\/", "/").strip()
    if not value:
        return ""
    return urljoin(share_url or "https://www.tvtfun.net/", value)


def candidate(source_url, source_type, share_html):
    media_url = extract_share_media_url(source_url, share_html)
    url = media_url or source_url
    video_type = normalize_video_type(source_type, url)
    unresolved_share = bool(source_url) and "/share/" in source_url and not media_url
    return url, video_type, bool(media_url), unresolved_share


def playback_url(url, video_type):
    if not url.startswith(("http://", "https://")):
        return url
    if video_type == "hls":
        return url
    if "/share/" in url:
        return url
    return "/_api/media/proxy?url=" + quote(url, safe="")


def execute(node_id, node_data, context):
    primary_url, primary_type, primary_resolved, primary_unresolved = candidate(
        context.get("resolved_source_url") or "",
        context.get("resolved_source_type") or "",
        context.get("share_html") or "",
    )
    fallback_url, fallback_type, fallback_resolved, _ = candidate(
        context.get("fallback_source_url") or "",
        context.get("fallback_source_type") or "",
        context.get("fallback_share_html") or "",
    )

    if primary_unresolved and (fallback_resolved or fallback_type == "hls"):
        url, video_type = fallback_url, fallback_type
    else:
        url, video_type = primary_url, primary_type

    url = playback_url(url, video_type)
    definitions = []
    if url:
        definitions.append({"url": url, "definition": "默认"})

    try:
        danmaku_payload = json.loads(context.get("danmaku_json") or "{}")
    except Exception:
        danmaku_payload = {}
    raw_comments = danmaku_payload.get("data") if isinstance(danmaku_payload, dict) else []
    if not isinstance(raw_comments, list):
        raw_comments = []

    danmakus = []
    for index, item in enumerate(raw_comments):
        if isinstance(item, dict):
            text = item.get("text") or item.get("content") or item.get("comment") or ""
            start = item.get("start", item.get("time", 0))
            mode = item.get("mode")
            color = item.get("color")
        elif isinstance(item, list) and len(item) >= 4:
            start, mode, color, text = item[0], item[1], item[2], item[3]
        else:
            continue
        if not text:
            continue
        danmakus.append({
            "id": "%s-%s" % (context.get("episode_id") or "danmaku", index),
            "text": str(text),
            "mode": normalize_mode(mode),
            "color": normalize_color(color),
            "start": normalize_start(start),
            "duration": 5000,
        })

    context["play_url"] = url
    context["play_video_type"] = video_type
    context["play_definitions"] = definitions
    context["play_danmakus"] = danmakus

